/* Rostrum practice content. Pure data — edit freely.
   Goal throughout: clear and confident, not "sounding native". Accent features are never errors. */
var RC = window.RC = window.RC || {};

RC.pronunciation = {
  minimalPairs: [
    {id:'mp1', sound:'/ɪ/ vs /iː/', a:'ship', b:'sheep', ipaA:'/ʃɪp/', ipaB:'/ʃiːp/', sentenceA:'The ship left at noon.', sentenceB:'The sheep left at noon.', tip:'For "ship" keep the tongue relaxed and the sound short. For "sheep" spread your lips a little, as if smiling, and hold it longer.', commonFor:['Spanish','Arabic','Mandarin','Tamil']},
    {id:'mp2', sound:'/ɪ/ vs /iː/', a:'live', b:'leave', ipaA:'/lɪv/', ipaB:'/liːv/', sentenceA:'I want to live here.', sentenceB:'I want to leave here.', tip:'"Live" is short and loose. "Leave" is long with a slight smile. Listeners use the length to tell them apart.', commonFor:['Spanish','Portuguese','Hindi']},
    {id:'mp3', sound:'/θ/ vs /t/', a:'thin', b:'tin', ipaA:'/θɪn/', ipaB:'/tɪn/', sentenceA:'It was a thin sheet.', sentenceB:'It was a tin sheet.', tip:'For "th", rest the tip of your tongue lightly between your teeth and blow air gently. For "t", tap the ridge behind your top teeth.', commonFor:['Hindi','Tamil','French','German']},
    {id:'mp4', sound:'/θ/ vs /t/', a:'three', b:'tree', ipaA:'/θriː/', ipaB:'/triː/', sentenceA:'I saw three by the road.', sentenceB:'I saw a tree by the road.', tip:'Let air flow over the tongue for "three". If "th" is hard, a soft dental "t" is usually still understood in context.', commonFor:['Hindi','Bengali','Mandarin']},
    {id:'mp5', sound:'/ð/ vs /d/', a:'they', b:'day', ipaA:'/ðeɪ/', ipaB:'/deɪ/', sentenceA:'They came early.', sentenceB:'Day came early.', tip:'"They" uses the same tongue-between-teeth position as "thin", but with your voice buzzing.', commonFor:['Hindi','Spanish','Mandarin','Arabic']},
    {id:'mp6', sound:'/θ/ vs /s/', a:'think', b:'sink', ipaA:'/θɪŋk/', ipaB:'/sɪŋk/', sentenceA:'Think about it.', sentenceB:'Sink about it.', tip:'For "s" the tongue stays behind the teeth. For "th" the tip comes forward to touch the edge of the teeth.', commonFor:['French','Mandarin','Japanese']},
    {id:'mp7', sound:'/v/ vs /w/', a:'vest', b:'west', ipaA:'/vest/', ipaB:'/west/', sentenceA:'Wear the vest.', sentenceB:'Go to the west.', tip:'For "v", rest your top teeth on your lower lip and buzz. For "w", round your lips like a small "oo" and keep teeth away from lips.', commonFor:['Hindi','Bengali','German','Gujarati']},
    {id:'mp8', sound:'/v/ vs /w/', a:'vine', b:'wine', ipaA:'/vaɪn/', ipaB:'/waɪn/', sentenceA:'The vine is growing.', sentenceB:'The wine is ageing.', tip:'Check with a finger: for "v" your lower lip touches your teeth; for "w" nothing touches.', commonFor:['Hindi','Marathi','German']},
    {id:'mp9', sound:'/v/ vs /b/', a:'very', b:'berry', ipaA:'/ˈveri/', ipaB:'/ˈberi/', sentenceA:'That is very good.', sentenceB:'That berry is good.', tip:'"B" closes both lips and releases a small pop. "V" never fully closes: air keeps flowing between teeth and lip.', commonFor:['Spanish','Korean','Japanese','Bengali']},
    {id:'mp10', sound:'/v/ vs /b/', a:'vote', b:'boat', ipaA:'/vəʊt/', ipaB:'/bəʊt/', sentenceA:'Did you vote?', sentenceB:'Did you see the boat?', tip:'Hold the "v" for a moment so it buzzes; a "b" is instant.', commonFor:['Spanish','Arabic']},
    {id:'mp11', sound:'/r/ vs /l/', a:'right', b:'light', ipaA:'/raɪt/', ipaB:'/laɪt/', sentenceA:'Turn right here.', sentenceB:'Turn the light on.', tip:'For "l", touch the ridge behind your teeth with the tongue tip. For "r", pull the tongue back without touching anything.', commonFor:['Japanese','Korean','Mandarin']},
    {id:'mp12', sound:'/r/ vs /l/', a:'collect', b:'correct', ipaA:'/kəˈlekt/', ipaB:'/kəˈrekt/', sentenceA:'Please collect the forms.', sentenceB:'Please correct the forms.', tip:'Slow it down: feel the tongue touch for "l" and float free for "r".', commonFor:['Japanese','Korean','Cantonese']},
    {id:'mp13', sound:'/s/ vs /ʃ/', a:'see', b:'she', ipaA:'/siː/', ipaB:'/ʃiː/', sentenceA:'I see the plan.', sentenceB:'She is the plan.', tip:'For "sh", round your lips slightly and pull the tongue back a little; the sound is lower and softer than "s".', commonFor:['Spanish','Tamil','Malayalam','Greek']},
    {id:'mp14', sound:'/s/ vs /ʃ/', a:'sort', b:'short', ipaA:'/sɔːt/', ipaB:'/ʃɔːt/', sentenceA:'Sort the list.', sentenceB:'Short list, please.', tip:'Push lips forward for "sh" like you are hushing someone.', commonFor:['Spanish','Tamil']},
    {id:'mp15', sound:'/z/ vs /dʒ/', a:'raise', b:'rage', ipaA:'/reɪz/', ipaB:'/reɪdʒ/', sentenceA:'They asked for a raise.', sentenceB:'They left in a rage.', tip:'"Z" is a continuous buzz like a bee. "J" (as in "rage") starts with the tongue pressed up, like "d", then releases into a buzz.', commonFor:['Hindi','Bengali','Gujarati']},
    {id:'mp16', sound:'/z/ vs /dʒ/', a:'zest', b:'jest', ipaA:'/zest/', ipaB:'/dʒest/', sentenceA:'She spoke with zest.', sentenceB:'She spoke in jest.', tip:'Start "jest" with your tongue pressed up, then release. Start "zest" with a gap so air buzzes through.', commonFor:['Hindi','Marathi','Arabic']},
    {id:'mp17', sound:'/æ/ vs /e/', a:'bad', b:'bed', ipaA:'/bæd/', ipaB:'/bed/', sentenceA:'It was a bad day.', sentenceB:'It was a bed day.', tip:'For "bad", drop your jaw more, as if starting to yawn. For "bed", the jaw is only half open.', commonFor:['Mandarin','Dutch','German','Hindi']},
    {id:'mp18', sound:'/æ/ vs /e/', a:'man', b:'men', ipaA:'/mæn/', ipaB:'/men/', sentenceA:'The man is here.', sentenceB:'The men are here.', tip:'The vowel carries the singular/plural meaning here, so open wide for "man".', commonFor:['Mandarin','Spanish','Tamil']},
    {id:'mp19', sound:'/ʌ/ vs /ɒ/', a:'cup', b:'cop', ipaA:'/kʌp/', ipaB:'/kɒp/', sentenceA:'Hand me the cup.', sentenceB:'Call the cop.', tip:'"Cup" is a short, relaxed "uh" in the middle of the mouth. "Cop" rounds the lips a little and sits further back.', commonFor:['Japanese','Spanish','Hindi']},
    {id:'mp20', sound:'/ʌ/ vs /ɒ/', a:'luck', b:'lock', ipaA:'/lʌk/', ipaB:'/lɒk/', sentenceA:'Good luck today.', sentenceB:'Good lock on the door.', tip:'Keep lips neutral for "luck"; round them slightly for "lock". In American English "lock" is more open — both are fine.', commonFor:['Spanish','Arabic']},
    {id:'mp21', sound:'/ʊ/ vs /uː/', a:'full', b:'fool', ipaA:'/fʊl/', ipaB:'/fuːl/', sentenceA:'The room is full.', sentenceB:'Don\'t be a fool.', tip:'"Full" is short and relaxed; "fool" is long with tightly rounded lips.', commonFor:['Spanish','Italian','Turkish']},
    {id:'mp22', sound:'/p/ vs /f/', a:'pan', b:'fan', ipaA:'/pæn/', ipaB:'/fæn/', sentenceA:'Hold the pan.', sentenceB:'Turn on the fan.', tip:'"P" closes both lips and pops. "F" rests top teeth on the lower lip and lets air hiss.', commonFor:['Arabic','Korean','Tagalog']},
    {id:'mp23', sound:'/p/ vs /b/', a:'pack', b:'back', ipaA:'/pæk/', ipaB:'/bæk/', sentenceA:'Pack the bag.', sentenceB:'Back the bag.', tip:'Hold paper in front of your mouth: "p" makes it flutter with a puff of air; "b" barely moves it.', commonFor:['Arabic','Hindi','Mandarin']},
    {id:'mp24', sound:'final /t/ vs /d/', a:'bet', b:'bed', ipaA:'/bet/', ipaB:'/bed/', sentenceA:'Place your bet.', sentenceB:'Make your bed.', tip:'The vowel before a final "d" is a little longer. Lengthen "bed", clip "bet".', commonFor:['German','Mandarin','Russian','Turkish']},
    {id:'mp25', sound:'final consonant present vs dropped', a:'wait', b:'way', ipaA:'/weɪt/', ipaB:'/weɪ/', sentenceA:'Please wait.', sentenceB:'Please, this way.', tip:'Finish the word: lightly touch the tongue to the ridge for the final "t", even if you do not release it loudly.', commonFor:['Mandarin','Vietnamese','Cantonese','Thai']},
    {id:'mp26', sound:'final /s/ (plural) present vs dropped', a:'cats', b:'cat', ipaA:'/kæts/', ipaB:'/kæt/', sentenceA:'The cats are outside.', sentenceB:'The cat is outside.', tip:'The final "s" carries the meaning "more than one" — let it hiss briefly.', commonFor:['Mandarin','Vietnamese','Thai']},
    {id:'mp27', sound:'/ŋ/ vs /n/', a:'sing', b:'sin', ipaA:'/sɪŋ/', ipaB:'/sɪn/', sentenceA:'They sing well.', sentenceB:'That was a sin.', tip:'For "ng", the back of the tongue lifts to the soft palate; for "n", the tip touches behind the teeth.', commonFor:['Spanish','Italian','Greek']},
    {id:'mp28', sound:'/h/ vs no /h/', a:'heat', b:'eat', ipaA:'/hiːt/', ipaB:'/iːt/', sentenceA:'Feel the heat.', sentenceB:'Time to eat.', tip:'"H" is just a breath before the vowel — like fogging a mirror.', commonFor:['French','Italian','Spanish']},
    {id:'mp29', sound:'/eɪ/ vs /e/', a:'late', b:'let', ipaA:'/leɪt/', ipaB:'/let/', sentenceA:'Sorry, I am late.', sentenceB:'Let me explain.', tip:'"Late" glides from "e" toward "ee". "Let" stays put.', commonFor:['Hindi','Spanish','Swahili']},
    {id:'mp30', sound:'/ɜː/ vs /ɑː/', a:'heard', b:'hard', ipaA:'/hɜːd/', ipaB:'/hɑːd/', sentenceA:'I heard it.', sentenceB:'It was hard.', tip:'"Heard" sits in the middle of the mouth with lips neutral. "Hard" opens the jaw wide and lowers the tongue.', commonFor:['Japanese','Korean','Arabic']}
  ],
  stress: [
    {word:'photograph', syllables:['PHO','to','graph'], stressIndex:0, note:'Noun — first syllable.'},
    {word:'photographer', syllables:['pho','TOG','ra','pher'], stressIndex:1, note:'Adding "-er" moves stress to the second syllable.'},
    {word:'photographic', syllables:['pho','to','GRAPH','ic'], stressIndex:2, note:'Words ending in "-ic" stress the syllable just before it.'},
    {word:'record', pos:'noun', syllables:['RE','cord'], stressIndex:0, note:'Noun: "a world RECORD".'},
    {word:'record', pos:'verb', syllables:['re','CORD'], stressIndex:1, note:'Verb: "please reCORD this".'},
    {word:'present', pos:'noun', syllables:['PRE','sent'], stressIndex:0, note:'Noun or adjective: "a birthday PRESent".'},
    {word:'present', pos:'verb', syllables:['pre','SENT'], stressIndex:1, note:'Verb: "I will preSENT the results".'},
    {word:'object', pos:'noun', syllables:['OB','ject'], stressIndex:0, note:'Noun: "a strange OBject".'},
    {word:'object', pos:'verb', syllables:['ob','JECT'], stressIndex:1, note:'Verb: "I obJECT to that".'},
    {word:'contract', pos:'noun', syllables:['CON','tract'], stressIndex:0, note:'Noun: "sign the CONtract".'},
    {word:'contract', pos:'verb', syllables:['con','TRACT'], stressIndex:1, note:'Verb: "muscles conTRACT".'},
    {word:'increase', pos:'noun', syllables:['IN','crease'], stressIndex:0, note:'Noun: "an INcrease in sales".'},
    {word:'increase', pos:'verb', syllables:['in','CREASE'], stressIndex:1, note:'Verb: "prices inCREASE".'},
    {word:'development', syllables:['de','VEL','op','ment'], stressIndex:1, note:'Common slip: stressing "-ment". Keep it light.'},
    {word:'economy', syllables:['e','CON','o','my'], stressIndex:1, note:'Compare: ecoNOMic (stress shifts).'},
    {word:'economic', syllables:['e','co','NOM','ic'], stressIndex:2, note:'"-ic" ending pulls stress forward.'},
    {word:'analysis', syllables:['a','NAL','y','sis'], stressIndex:1, note:'Compare: ANalyse / ANalyze.'},
    {word:'comfortable', syllables:['COM','for','ta','ble'], stressIndex:0, note:'Often said in three syllables: COMF-ta-ble.'},
    {word:'determine', syllables:['de','TER','mine'], stressIndex:1, note:'Ends like "min", not like "mine".'},
    {word:'committee', syllables:['com','MIT','tee'], stressIndex:1, note:'Middle syllable carries the stress.'}
  ],
  shadowing: [
    {id:'sh1', text:'Good morning, everyone. / Thanks for being here.', focus:'rhythm', level:1},
    {id:'sh2', text:'I\'d like to start / with one simple question.', focus:'rhythm', level:1},
    {id:'sh3', text:'Pick it up / and put it on the table.', focus:'linking', level:1},
    {id:'sh4', text:'Can I ask you something? / It won\'t take long.', focus:'intonation', level:1},
    {id:'sh5', text:'We didn\'t miss the deadline. / We missed the brief.', focus:'emphasis', level:2},
    {id:'sh6', text:'Last year / we had three goals, / and we hit two of them.', focus:'rhythm', level:2},
    {id:'sh7', text:'Turn it off / and leave it on the shelf.', focus:'linking', level:2},
    {id:'sh8', text:'Are you joining us on Friday, / or is next week better?', focus:'intonation', level:2},
    {id:'sh9', text:'The problem isn\'t the price. / The problem is the timing.', focus:'emphasis', level:3},
    {id:'sh10', text:'If we wait another month, / the window closes, / and we start again from zero.', focus:'rhythm', level:3},
    {id:'sh11', text:'What I\'m asking for / is a decision, / not a discussion.', focus:'emphasis', level:3},
    {id:'sh12', text:'She told us about it / at the end of an hour-long meeting.', focus:'linking', level:3},
    {id:'sh13', text:'You can have it fast, / you can have it cheap, / or you can have it right.', focus:'intonation', level:4},
    {id:'sh14', text:'Nobody remembers the slide. / Everybody remembers the story.', focus:'emphasis', level:4},
    {id:'sh15', text:'Here is what I know, / here is what I don\'t, / and here is what I\'ll do next.', focus:'rhythm', level:4}
  ],
  twisters: [
    {level:1, text:'Red lorry, yellow lorry.'},
    {level:1, text:'Vera wove a wide velvet veil.'},
    {level:1, text:'Six slim ships slid south.'},
    {level:2, text:'Three thin thinkers thought thoroughly through Thursday.'},
    {level:2, text:'Willow wanted very warm woollen vests.'},
    {level:2, text:'She sells sea shells by the sea shore.'},
    {level:3, text:'Rory\'s lawn rake rarely rakes really well.'},
    {level:3, text:'The sixth sheep\'s sick, so she shifts the shed.'},
    {level:4, text:'Brave Brenda verified twelve vivid brochures before breakfast.'},
    {level:4, text:'Theo\'s thirty-third thesis thoroughly thrilled the threadbare theatre.'}
  ],
  intonation: [
    {line:'I didn\'t say she took it.', variants:[
      {emphasis:'I', meaning:'Someone else said it.'},
      {emphasis:'didn\'t', meaning:'I deny saying it.'},
      {emphasis:'say', meaning:'I implied it, but didn\'t say it.'},
      {emphasis:'she', meaning:'Someone else took it.'},
      {emphasis:'took', meaning:'She borrowed it, maybe.'},
      {emphasis:'it', meaning:'She took something else.'}]},
    {line:'We need this by Friday.', variants:[
      {emphasis:'We', meaning:'Our team, not theirs, needs it.'},
      {emphasis:'this', meaning:'This item, not the other one.'},
      {emphasis:'Friday', meaning:'Not Monday — Friday is the deadline.'}]},
    {line:'That\'s a great idea.', variants:[
      {emphasis:'great', meaning:'Genuine enthusiasm (falling ending).'},
      {emphasis:'That\'s', meaning:'This one, unlike the others.'},
      {emphasis:'idea', meaning:'Said with a rise: "That\'s a great idea?" — doubt.'}]},
    {line:'You finished the report.', variants:[
      {emphasis:'finished', meaning:'Falling ending: a statement of fact.'},
      {emphasis:'report', meaning:'Rising ending: a surprised question.'},
      {emphasis:'You', meaning:'You, not someone else, did it.'}]},
    {line:'I can help you tomorrow.', variants:[
      {emphasis:'I', meaning:'I can, even if others can\'t.'},
      {emphasis:'can', meaning:'It is possible — reassurance.'},
      {emphasis:'tomorrow', meaning:'Not today — tomorrow.'}]},
    {line:'Our budget is fixed.', variants:[
      {emphasis:'fixed', meaning:'Falling ending: final, not negotiable.'},
      {emphasis:'Our', meaning:'Ours is fixed; yours may not be.'},
      {emphasis:'budget', meaning:'The budget is fixed; other things can move.'}]},
    {line:'Endings: statements fall', variants:[
      {emphasis:'falling', meaning:'"This is the plan." — pitch steps down on "plan" and you stop. Sounds decided.'},
      {emphasis:'rising', meaning:'"This is the plan?" — pitch goes up. Sounds like you are asking permission.'}]},
    {line:'Endings: lists rise, then fall', variants:[
      {emphasis:'rise', meaning:'"We need time, ↗ money, ↗" — rise on each item to show more is coming.'},
      {emphasis:'fall', meaning:'"…and a clear owner. ↘" — fall on the last item to close the list.'}]}
  ]
};

RC.grammar = [
  {id:'g1', name:'Subject–verb agreement (don\'t / doesn\'t)', wrong:'He don\'t know the answer.', right:'He doesn\'t know the answer.', rule:'With he, she, it or a single name, use "doesn\'t".', detect:"\\b(he|she|it)\\s+don'?t\\b", drills:[{prompt:'Fix: She don\'t like meetings.', answer:'She doesn\'t like meetings.'},{prompt:'Fix: It don\'t matter.', answer:'It doesn\'t matter.'}]},
  {id:'g2', name:'Third-person -s', wrong:'She go to work by bus.', right:'She goes to work by bus.', rule:'In the present simple, add -s to the verb after he, she or it.', detect:"(?<!\\b(?:does|did|do|doesn't|didn't|will|won't|can|could|would|should|may|might|must|let|lets|make|makes|made|help|see|saw|watch|hear|heard)\\s+)\\b(he|she|it)\\s+(go|do|have|want|need|like|know|say|make|work|think)\\b", drills:[{prompt:'Fix: He work in finance.', answer:'He works in finance.'},{prompt:'Fix: It need more time.', answer:'It needs more time.'}]},
  {id:'g3', name:'Double verb ending (knows after does)', wrong:'He doesn\'t knows the plan.', right:'He doesn\'t know the plan.', rule:'After do, does or did, use the base verb with no -s or -ed.', detect:"\\b(doesn'?t|didn'?t)\\s+\\w+(ed|[^s']s)\\b", drills:[{prompt:'Fix: Did you finished it?', answer:'Did you finish it?'},{prompt:'Fix: She didn\'t wanted to go.', answer:'She didn\'t want to go.'}]},
  {id:'g4', name:'Was / were agreement', wrong:'We was ready on time.', right:'We were ready on time.', rule:'Use "were" with we, you and they.', detect:"\\b(we|you|they)\\s+was\\b", drills:[{prompt:'Fix: They was late.', answer:'They were late.'},{prompt:'Fix: You was right.', answer:'You were right.'}]},
  {id:'g5', name:'Article before a singular job or noun', wrong:'She is engineer.', right:'She is an engineer.', rule:'A singular countable noun needs "a", "an" or "the".', detect:"\\b(is|am|was|i'?m|he'?s|she'?s)\\s+(engineer|doctor|teacher|manager|student|developer|designer|lawyer|nurse|accountant)\\b", drills:[{prompt:'Fix: I am student.', answer:'I am a student.'},{prompt:'Fix: He is manager here.', answer:'He is a manager here.'}]},
  {id:'g6', name:'"A" vs "an"', wrong:'It was a honest mistake.', right:'It was an honest mistake.', rule:'Use "an" before a vowel sound, even if the letter is a consonant (an hour, an honest).', detect:"\\ba\\s+(honest|hour|honour|honor|apple|idea|update|issue|example|engineer|important|email|answer)\\b", drills:[{prompt:'Fix: We need a update.', answer:'We need an update.'},{prompt:'Fix: Wait a hour.', answer:'Wait an hour.'}]},
  {id:'g7', name:'"The" with unique or known things', wrong:'Sun was very bright.', right:'The sun was very bright.', rule:'Use "the" for unique things and things both speakers already know.', detect:"^(sun|moon|internet|government|weather|meeting)\\s+(was|is|were)\\b", drills:[{prompt:'Fix: Internet is down.', answer:'The internet is down.'},{prompt:'Fix: Meeting was useful.', answer:'The meeting was useful.'}]},
  {id:'g8', name:'Since vs for', wrong:'I have worked here since five years.', right:'I have worked here for five years.', rule:'"For" + a length of time; "since" + a starting point.', detect:"\\bsince\\s+(\\d+|one|two|three|four|five|six|seven|eight|nine|ten|many|several|a few)\\s+(years?|months?|weeks?|days?|hours?)\\b", drills:[{prompt:'Fix: She has lived here since ten years.', answer:'She has lived here for ten years.'},{prompt:'Fix: I have waited since two hours.', answer:'I have waited for two hours.'}]},
  {id:'g9', name:'Present perfect with duration', wrong:'I am working here for three years.', right:'I have been working here for three years.', rule:'For something that started in the past and continues now, use "have been" + -ing.', detect:"\\b(i am|i'm|we are|we're)\\s+\\w+ing\\s+here\\s+(for|since)\\b", drills:[{prompt:'Fix: I am living here since 2019.', answer:'I have been living here since 2019.'},{prompt:'Fix: We are working on this for weeks.', answer:'We have been working on this for weeks.'}]},
  {id:'g10', name:'Past simple with a finished time', wrong:'I have seen him yesterday.', right:'I saw him yesterday.', rule:'With a finished time (yesterday, last week, in 2020), use the past simple.', detect:"\\b(have|has|'ve)\\s+((?!since\\b)\\w+\\s+){1,3}(yesterday|last\\s+(week|month|year|night))\\b", drills:[{prompt:'Fix: We have met last week.', answer:'We met last week.'},{prompt:'Fix: I have sent it yesterday.', answer:'I sent it yesterday.'}]},
  {id:'g11', name:'Double negative', wrong:'I don\'t need nothing.', right:'I don\'t need anything.', rule:'In standard English, one negative per clause: "don\'t … anything".', detect:"\\b(don'?t|didn'?t|doesn'?t|can'?t|won'?t|never)\\s+(\\w+\\s+)?(nothing|nobody|none|nowhere)\\b", drills:[{prompt:'Fix: We didn\'t see nobody.', answer:'We didn\'t see anybody.'},{prompt:'Fix: It won\'t change nothing.', answer:'It won\'t change anything.'}]},
  {id:'g12', name:'Double comparative', wrong:'This plan is more better.', right:'This plan is better.', rule:'Short adjectives take -er OR "more", never both.', detect:"\\bmore\\s+(better|worse|bigger|faster|easier|cheaper|smaller|higher|lower)\\b", drills:[{prompt:'Fix: It\'s more easier now.', answer:'It\'s easier now.'},{prompt:'Fix: This is more cheaper.', answer:'This is cheaper.'}]},
  {id:'g13', name:'Double superlative', wrong:'She is the most smartest person here.', right:'She is the smartest person here.', rule:'Use -est OR "most", not both.', detect:"\\bmost\\s+\\w+est\\b", drills:[{prompt:'Fix: It was the most fastest option.', answer:'It was the fastest option.'},{prompt:'Fix: The most easiest way is this.', answer:'The easiest way is this.'}]},
  {id:'g14', name:'Less vs fewer', wrong:'We had less complaints this month.', right:'We had fewer complaints this month.', rule:'"Fewer" for things you can count; "less" for amounts (less time, fewer hours).', detect:"\\bless\\s+(people|complaints|errors|mistakes|items|customers|bugs|meetings|days|hours|questions|problems)\\b", drills:[{prompt:'Fix: There are less people today.', answer:'There are fewer people today.'},{prompt:'Fix: Less mistakes this time.', answer:'Fewer mistakes this time.'}]},
  {id:'g15', name:'Uncountable nouns (no plural)', wrong:'She gave me some useful informations.', right:'She gave me some useful information.', rule:'Information, advice, feedback, equipment, furniture and luggage have no plural form.', detect:"\\b(informations|advices|feedbacks|equipments|furnitures|luggages|knowledges|researches|softwares)\\b", drills:[{prompt:'Fix: Thanks for the feedbacks.', answer:'Thanks for the feedback.'},{prompt:'Fix: He gave me two advices.', answer:'He gave me two pieces of advice.'}]},
  {id:'g16', name:'Many vs much', wrong:'We don\'t have much options.', right:'We don\'t have many options.', rule:'"Many" with countable plurals; "much" with uncountables.', detect:"\\bmuch\\s+(options|people|ideas|questions|problems|things|reasons|days|issues)\\b", drills:[{prompt:'Fix: How much people came?', answer:'How many people came?'},{prompt:'Fix: There aren\'t much issues.', answer:'There aren\'t many issues.'}]},
  {id:'g17', name:'Pronoun case in subjects', wrong:'Me and him went to the client.', right:'He and I went to the client.', rule:'As the subject, use I, he, she, we, they — and put yourself last.', detect:"^(me|him|her|them|us)\\s+and\\s+\\w+\\s+(went|are|were|did|have|will|met|said)\\b", drills:[{prompt:'Fix: Me and her are presenting.', answer:'She and I are presenting.'},{prompt:'Fix: Him and me did it.', answer:'He and I did it.'}]},
  {id:'g18', name:'"Between you and I"', wrong:'Between you and I, it was risky.', right:'Between you and me, it was risky.', rule:'After a preposition (between, with, for), use me, him, her, us, them.', detect:"\\b(between|with|for|to)\\s+(you|him|her|them)\\s+and\\s+i\\b", drills:[{prompt:'Fix: Send it to Priya and I.', answer:'Send it to Priya and me.'},{prompt:'Fix: This stays with you and I.', answer:'This stays with you and me.'}]},
  {id:'g19', name:'Question word order', wrong:'Why you are leaving early?', right:'Why are you leaving early?', rule:'In a question, put the helper verb before the subject: "Why are you…?"', detect:"^(why|what|where|when|how)\\s+(you|he|she|they|we|it)\\s+(are|is|were|was|will|can|have|has)\\b", drills:[{prompt:'Fix: Where you are going?', answer:'Where are you going?'},{prompt:'Fix: What he is saying?', answer:'What is he saying?'}]},
  {id:'g20', name:'Embedded question order', wrong:'Can you tell me where is the room?', right:'Can you tell me where the room is?', rule:'Inside a longer question or statement, use normal order: "where the room is".', detect:"\\b(tell me|know|wonder|ask)\\s+(where|what|when|why|how)\\s+(is|are|was|were)\\s+(the|your|his|her|their|this|that)\\b", drills:[{prompt:'Fix: Do you know what is the time?', answer:'Do you know what the time is?'},{prompt:'Fix: I wonder why is the price so high.', answer:'I wonder why the price is so high.'}]},
  {id:'g21', name:'Reported speech tense', wrong:'She said that she will call tomorrow.', right:'She said that she would call tomorrow.', rule:'After "said", shift will → would, can → could (unless it is still true and you want to stress that).', detect:"\\b(said|told\\s+\\w+)\\s+(that\\s+)?(he|she|they|we|i)\\s+will\\b", drills:[{prompt:'Fix: He told me he will help.', answer:'He told me he would help.'},{prompt:'Fix: They said they can come.', answer:'They said they could come.'}]},
  {id:'g22', name:'First conditional', wrong:'If it will rain, we will cancel.', right:'If it rains, we will cancel.', rule:'After "if" for a future condition, use the present simple, not "will".', detect:"\\bif\\s+\\w+\\s+will\\b", drills:[{prompt:'Fix: If you will call, I will answer.', answer:'If you call, I will answer.'},{prompt:'Fix: If the client will agree, we start Monday.', answer:'If the client agrees, we start Monday.'}]},
  {id:'g23', name:'Second conditional', wrong:'If I would know, I would tell you.', right:'If I knew, I would tell you.', rule:'Imagined present: "If + past, would + verb".', detect:"\\bif\\s+(i|you|he|she|we|they)\\s+would\\b", drills:[{prompt:'Fix: If I would have time, I would help.', answer:'If I had time, I would help.'},{prompt:'Fix: If she would be here, she would agree.', answer:'If she were here, she would agree.'}]},
  {id:'g24', name:'Third conditional', wrong:'If I would have known, I would have come.', right:'If I had known, I would have come.', rule:'Past regret: "If + had + past participle, would have + past participle".', detect:"\\bif\\s+\\w+\\s+would\\s+have\\b", drills:[{prompt:'Fix: If we would have started earlier, we would have finished.', answer:'If we had started earlier, we would have finished.'},{prompt:'Fix: If you would have asked, I would have said yes.', answer:'If you had asked, I would have said yes.'}]},
  {id:'g25', name:'"Discuss about" (redundant preposition)', wrong:'Let\'s discuss about the budget.', right:'Let\'s discuss the budget.', rule:'"Discuss" already means "talk about" — no "about" needed.', detect:"\\bdiscuss(ed|ing)?\\s+about\\b", drills:[{prompt:'Fix: We discussed about the timeline.', answer:'We discussed the timeline.'},{prompt:'Fix: I want to discuss about salary.', answer:'I want to discuss salary.'}]},
  {id:'g26', name:'"Return back" (redundancy)', wrong:'I will return back the laptop on Monday.', right:'I will return the laptop on Monday.', rule:'"Return" already means "go or give back".', detect:"\\breturn(ed|ing)?\\s+back\\b", drills:[{prompt:'Fix: Please return back the form.', answer:'Please return the form.'},{prompt:'Fix: She returned back to the office.', answer:'She returned to the office.'}]},
  {id:'g27', name:'"Revert back" (regional usage)', wrong:'I will revert back to you by Friday.', right:'I will get back to you by Friday.', rule:'Common and understood in some regions; for international audiences, "get back to you" or "reply" is clearer. Not an error — an audience choice.', detect:"\\brevert(ed|ing)?\\s+(back\\s+)?to\\s+(you|me|him|her|them|us)\\b", drills:[{prompt:'Adapt for an international client: Kindly revert by EOD.', answer:'Please reply by the end of the day.'},{prompt:'Adapt: I will revert back shortly.', answer:'I will get back to you shortly.'}]},
  {id:'g28', name:'"Do the needful" (regional usage)', wrong:'Please do the needful.', right:'Please sign and return the form by Friday.', rule:'Widely used in South Asian English; international listeners may not know what action you mean. Name the exact action instead.', detect:"\\bdo\\s+the\\s+needful\\b", drills:[{prompt:'Adapt: Kindly do the needful regarding the invoice.', answer:'Please approve the invoice by Thursday.'},{prompt:'Adapt: Do the needful and inform.', answer:'Please update the record and let me know when it\'s done.'}]},
  {id:'g29', name:'"Prepone" (regional usage)', wrong:'Can we prepone the meeting?', right:'Can we move the meeting earlier?', rule:'Standard in Indian English; elsewhere say "move it earlier" or "bring it forward".', detect:"\\bprepon(e|ed|ing)\\b", drills:[{prompt:'Adapt: The call is preponed to 3 pm.', answer:'The call has been moved earlier, to 3 pm.'},{prompt:'Adapt: Let\'s prepone the launch.', answer:'Let\'s bring the launch forward.'}]},
  {id:'g30', name:'Preposition: married to / with', wrong:'She is married with an architect.', right:'She is married to an architect.', rule:'You are married TO someone.', detect:"\\bmarried\\s+with\\s+(a|an|the|my|his|her)\\b", drills:[{prompt:'Fix: He got married with Ana.', answer:'He got married to Ana.'},{prompt:'Fix: I\'m married with a teacher.', answer:'I\'m married to a teacher.'}]},
  {id:'g31', name:'Preposition: depend on', wrong:'It depends of the budget.', right:'It depends on the budget.', rule:'Depend ON, rely ON.', detect:"\\bdepend(s|ed|ing)?\\s+(of|from)\\b", drills:[{prompt:'Fix: It depends from the client.', answer:'It depends on the client.'},{prompt:'Fix: We depend of their data.', answer:'We depend on their data.'}]},
  {id:'g32', name:'Preposition: in / on / at time', wrong:'The meeting is in Monday.', right:'The meeting is on Monday.', rule:'ON days and dates, IN months and years, AT clock times.', detect:"\\bin\\s+(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\\b", drills:[{prompt:'Fix: See you in Friday.', answer:'See you on Friday.'},{prompt:'Fix: The call is on 3 pm.', answer:'The call is at 3 pm.'}]},
  {id:'g33', name:'Preposition: arrive in / at', wrong:'We arrived to the office early.', right:'We arrived at the office early.', rule:'Arrive AT a place, arrive IN a city or country — never "arrive to".', detect:"\\barriv(e|ed|es|ing)\\s+to\\b", drills:[{prompt:'Fix: She arrived to London.', answer:'She arrived in London.'},{prompt:'Fix: They arrive to the airport at six.', answer:'They arrive at the airport at six.'}]},
  {id:'g34', name:'Verb + to / -ing', wrong:'I suggest to start with the data.', right:'I suggest starting with the data.', rule:'Suggest, recommend, avoid, consider and enjoy take -ing (or "suggest that we…").', detect:"\\b(suggest|recommend|avoid|consider|enjoy)(s|ed)?\\s+to\\s+\\w+", drills:[{prompt:'Fix: We should avoid to repeat this.', answer:'We should avoid repeating this.'},{prompt:'Fix: I recommend to use the template.', answer:'I recommend using the template.'}]},
  {id:'g35', name:'Explain to someone', wrong:'Can you explain me the plan?', right:'Can you explain the plan to me?', rule:'Explain something TO someone. The same for describe and suggest.', detect:"\\b(explain|describe)\\s+(me|him|her|us|them)\\b", drills:[{prompt:'Fix: Let me explain you the issue.', answer:'Let me explain the issue to you.'},{prompt:'Fix: Describe me the process.', answer:'Describe the process to me.'}]},
  {id:'g36', name:'Past tense: irregular verbs', wrong:'I have went there before.', right:'I have gone there before.', rule:'After have / has / had, use the past participle: gone, done, seen, written.', detect:"\\b(have|has|had)\\s+(went|did|saw|wrote|took|ate|spoke|came|ran|began|chose)\\b", drills:[{prompt:'Fix: She has wrote the summary.', answer:'She has written the summary.'},{prompt:'Fix: We had took the train.', answer:'We had taken the train.'}]},
  {id:'g37', name:'"Could of" (sounds like could\'ve)', wrong:'We could of finished sooner.', right:'We could have finished sooner.', rule:'"Could\'ve" is short for "could have" — not "could of".', detect:"\\b(could|should|would|must|might)\\s+of\\b", drills:[{prompt:'Fix: You should of called.', answer:'You should have called.'},{prompt:'Fix: It must of been late.', answer:'It must have been late.'}]},
  {id:'g38', name:'Stative verbs in continuous form', wrong:'I am knowing the answer.', right:'I know the answer.', rule:'Verbs of knowing, wanting and owning (know, understand, want, own, believe) are rarely used with -ing.', detect:"\\b(am|is|are)\\s+(knowing|understanding|wanting|owning|believing|needing|preferring)\\b", drills:[{prompt:'Fix: She is wanting a refund.', answer:'She wants a refund.'},{prompt:'Fix: I am understanding your point.', answer:'I understand your point.'}]},
  {id:'g39', name:'"Each / every" + singular', wrong:'Every employees has a badge.', right:'Every employee has a badge.', rule:'Each and every are followed by a singular noun.', detect:"\\b(every|each)\\s+(employees|members|students|people|customers|teams|projects|days)\\b", drills:[{prompt:'Fix: Each teams presents on Friday.', answer:'Each team presents on Friday.'},{prompt:'Fix: Every customers matters.', answer:'Every customer matters.'}]},
  {id:'g40', name:'Plural after "one of the"', wrong:'She is one of the best speaker here.', right:'She is one of the best speakers here.', rule:'"One of the…" is followed by a plural noun.', detect:"\\bone of the\\s+(best|biggest|most\\s+\\w+|top|main|key)\\s+(speaker|reason|problem|idea|customer|project|person|team|option)\\b", drills:[{prompt:'Fix: It is one of the main reason.', answer:'It is one of the main reasons.'},{prompt:'Fix: He is one of the key person.', answer:'He is one of the key people.'}]}
];

